import { useEffect, useState } from "react";
import DashboardLayout from "../../component/DashboardLayout";
import { Pagination } from "@/type/pagination";
import { InventoryMovement } from "@/type/inventory_movement";
import { Button, Image, Table, Typography, message } from "antd";
import {
    ReloadOutlined,
} from '@ant-design/icons';
import { RequestParam } from "@/type/request_param";
import axiosInstance from "@/utils/axiosInstance";
import Title from "antd/es/typography/Title";
const BarangMasuk: React.FC = () => {

    const [outs, setData] = useState<Pagination<InventoryMovement>>({
        current_page: 0,
        data: [],
        last_page: 1,
        total: 0,
    });
    
    const [loading, setLoading] = useState<boolean>(false);
    const [requestParam, setParamRequst] = useState<RequestParam>({
        table: 'inventory_movements',
        limit: 10,
        page: 1,
        where: [{
            type: 'in',
        }],
        request_column_relation: ['inventory', 'item', 'inventory.location']
    });

    const column = [
        {
            title: 'No',
            dataIndex: '',
            key: '',
            render: (_: any, record: any, index: number) => index + 1,
        },
        // {
        //     title: 'Photo',
        //     dataIndex:'photo', 
        //     key: 'photo',
        //     render: (_: any, record: InventoryMovement) => record.item?.photo != null ? <Image
        //         width={40}
        //         src={`${process.env.NEXT_PUBLIC_BE}/storage/${record.item?.photo}`}
        //         fallback="data:image/png;base64,"
        //     /> : '',
        // },
        {
            title: 'SKU',
            dataIndex: '',
            key: 'sku',
            render: (_: any, record: InventoryMovement, index: number) => <p>
                <Typography.Link href="/">{record.item.sku}</Typography.Link>
            </p>
        },
        {
            title: 'Item',
            dataIndex: '',
            key: 'item',
            render: (_: any, record: InventoryMovement, index: number) => <p>{record.item.name}</p>
        },
        {
            title: 'Quantity',
            dataIndex: '',
            key: 'item',
            render: (_: any, record: InventoryMovement, index: number) => <p>{record.quantity} {record.unit_name}</p>
        },
        {
            title: 'Gudang',
            dataIndex: '',
            key: 'item',
            render: (_: any, record: InventoryMovement, index: number) => <p>{record.inventory.location?.name}</p>
        },
        {
            title: 'Operasi',
            key: 'action',
            render: (text: any, record: InventoryMovement) => (
                <Typography.Link href={`/staff/${record.product_id}`}>
                        Detail
                </Typography.Link>
            ),
        },
    ]

    const fetch = async () => {
        setLoading(true);
        try {
            const response = await axiosInstance.post('/search', requestParam);
            if(response.status == 200){
                // console.log(response.data.data.data);

                setData(response.data.data);
            }
        } catch (error: any) {
            message.error(`${error.response?.data?.message}`);
        } finally {
            setLoading(false);
        }
    }


    useEffect(() => {
        fetch();
    }, [])


    return (
        <DashboardLayout>
            <Title level={2}>Daftar Barang Masuk</Title>
            <Button icon={<ReloadOutlined/>} type="default" onClick={fetch} className="my-3" >Reload</Button>
            <Table columns={column} dataSource={outs!.data} pagination={false} rowKey={(record) => record.id} loading={loading} />
        </DashboardLayout>
    );
}

export default BarangMasuk;